package net.minecraft.network;import java.io.*;public class RegistryFriendlyByteBuf {public ByteArrayOutputStream out=new ByteArrayOutputStream();public DataOutputStream write=new DataOutputStream(out);public DataInputStream read;public RegistryFriendlyByteBuf(Object b,Object registry){read=new DataInputStream(new ByteArrayInputStream((byte[])b));}public void writeUtf(String s,int max)throws Exception{if(s.length()>max)throw new IllegalArgumentException();write.writeUTF(s);}public String readUtf(int max)throws Exception{String s=read.readUTF();if(s.length()>max)throw new IllegalArgumentException();return s;}public int readableBytes()throws Exception{return out.size()>0?out.size():read.available();}public void getBytes(int start,byte[]b){System.arraycopy(out.toByteArray(),start,b,0,b.length);}public void release(){}}